  "browser.controlPaused": "En pause · cliquez sur Reprendre pour continuer",
  "browser.externalPages.hint": "Activé, les onglets du navigateur intégré accèdent à Internet via un proxy local réservé au navigateur (127.0.0.1 uniquement, un nouvel identifiant à chaque exécution, pas de déchiffrement HTTPS, pas de cache ; il se ferme avec le dernier onglet ou à la fermeture de l’app). Seuls les onglets du navigateur peuvent l’utiliser : la fenêtre de l’app, les plugins et les pages d’artefacts restent sans réseau. Le désactiver coupe aussitôt les connexions ouvertes aux sites web. Les adresses LAN / tailnet ne dépendent pas de ce réglage : une adresse que vous ouvrez dans la barre d’adresse ne fonctionne que dans cet onglet, et les pages ne peuvent pas atteindre seules d’autres adresses LAN ou locales.",
